using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class SuppressSourceGenerationAnalyzerTests
{
    private static async Task RunAsync(string source)
    {
        var test = new VerifyCS.Test
        {
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        test.TestState.Sources.Add(source);
        await test.RunAsync();
    }

    [Fact]
    public async Task SuppressedType_DerivedKeys_NoSpuriousDiagnosticsOrCrash()
    {
        string source = """
            using MessagePack;

            public class MyKeyAttribute : KeyAttribute
            {
                public MyKeyAttribute(int x) : base(x) { }
            }

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [MyKey(0)]
                public int A { get; set; }

                [MyKey(1)]
                public int B { get; set; }
            }
            """;
        await RunAsync(source);
    }

    [Fact]
    public async Task SuppressedType_DerivedAndRegularKeys_NoSpuriousDiagnosticsOrCrash()
    {
        string source = """
            using MessagePack;

            public class MyKeyAttribute : KeyAttribute
            {
                public MyKeyAttribute(int x) : base(x) { }
            }

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [Key(0)]
                public int A { get; set; }

                [MyKey(1)]
                public int B { get; set; }
            }
            """;
        await RunAsync(source);
    }

    [Fact]
    public async Task SuppressedType_WithDerivedKey_StillReportsMissingKey()
    {
        string source = """
            using MessagePack;

            public class MyKeyAttribute : KeyAttribute
            {
                public MyKeyAttribute(int x) : base(x) { }
            }

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [MyKey(0)]
                public int A { get; set; }

                public int {|MsgPack004:B|} { get; set; }
            }
            """;
        await RunAsync(source);
    }
}
